(() => {
  const C = window.JALAL;
  // Layer rectangles in box-image pixels (box.webp is 1000×752). Generated by tools/layers.mjs.
  const BOX = { w: 1000, h: 752 };
  const LAYERS = {
    onion: { x: 115, y: 259, w: 653, h: 322 },
    mushroom: { x: 182, y: 259, w: 586, h: 253 },
    cheese: { x: 158, y: 276, w: 576, h: 242 },
    bacon: { x: 135, y: 232, w: 632, h: 361 },
    ketchup: { x: 193, y: 275, w: 485, h: 212 },
    mustard: { x: 193, y: 275, w: 485, h: 212 },
    mayo: { x: 193, y: 285, w: 485, h: 212 },
    pink: { x: 193, y: 267, w: 485, h: 212 },
  };
  // Saucy toppings get the squeeze sound instead of a soft drop.
  const TOPPING_SOUND = { cheese: 'squeeze', mushroom: 'squeeze' };

  const $ = (s) => document.querySelector(s);
  const img = (n) => `assets/img/${n}.webp`;
  const fa = (n) => new Intl.NumberFormat('fa-IR').format(n);
  const wait = (ms) => new Promise((r) => setTimeout(r, ms));
  const reduce = matchMedia('(prefers-reduced-motion: reduce)').matches;
  const speed = reduce ? 0.35 : 1;

  /* ---------------- sound ---------------- */
  const Sound = {
    muted: false,
    ctx: null,
    ac() { this.ctx ??= new (window.AudioContext || window.webkitAudioContext)(); if (this.ctx.state === 'suspended') this.ctx.resume(); return this.ctx; },
    play(key) {
      const cfg = C.sounds[key];
      if (!cfg || this.muted) return;
      if (cfg.src.startsWith('synth:')) return this.synth[cfg.src.slice(6)].call(this);
      const a = new Audio(`assets/sfx/${cfg.src}`);
      a.volume = cfg.volume ?? 1;
      a.play().catch(() => {});
      if (cfg.max) gsap.to(a, { volume: 0, duration: 0.35, delay: Math.max(0, cfg.max - 0.35), onComplete: () => a.pause() });
    },
    noise(sec) {
      const a = this.ac(), buf = a.createBuffer(1, a.sampleRate * sec, a.sampleRate), d = buf.getChannelData(0);
      for (let i = 0; i < d.length; i++) d[i] = Math.random() * 2 - 1;
      return buf;
    },
    synth: {
      // Wet sauce squirt: band-passed noise sweeping up plus a short low "blurp".
      squirt() {
        const a = this.ac(), t = a.currentTime;
        const src = a.createBufferSource(); src.buffer = this.noise(0.6);
        const bp = a.createBiquadFilter(); bp.type = 'bandpass'; bp.Q.value = 3;
        bp.frequency.setValueAtTime(500, t); bp.frequency.exponentialRampToValueAtTime(2200, t + 0.45);
        const g = a.createGain(); g.gain.setValueAtTime(0, t);
        g.gain.linearRampToValueAtTime(0.7, t + 0.03); g.gain.exponentialRampToValueAtTime(0.01, t + 0.55);
        src.connect(bp).connect(g).connect(a.destination); src.start(t); src.stop(t + 0.6);
        const o = a.createOscillator(); o.type = 'sine';
        o.frequency.setValueAtTime(180, t); o.frequency.exponentialRampToValueAtTime(70, t + 0.12);
        const og = a.createGain(); og.gain.setValueAtTime(0.4, t); og.gain.exponentialRampToValueAtTime(0.01, t + 0.14);
        o.connect(og).connect(a.destination); o.start(t); o.stop(t + 0.15);
      },
      // Thermal receipt printer: rapid buzzy ticks.
      receipt() {
        const a = this.ac(), t = a.currentTime;
        for (let i = 0; i < 40; i++) {
          const s = t + i * 0.034;
          const o = a.createOscillator(); o.type = 'square'; o.frequency.value = 95 + Math.random() * 20;
          const f = a.createBiquadFilter(); f.type = 'highpass'; f.frequency.value = 700;
          const g = a.createGain(); g.gain.setValueAtTime(0.14, s); g.gain.exponentialRampToValueAtTime(0.001, s + 0.028);
          o.connect(f).connect(g).connect(a.destination); o.start(s); o.stop(s + 0.03);
        }
      },
    },
  };
  try { Sound.muted = localStorage.getItem('jalal-muted') === '1'; } catch {}

  /* ---------------- state ---------------- */
  const state = { toppings: new Set(), sauces: new Set(), sides: new Set(), qty: 1 };
  let queue = Promise.resolve();
  const enqueue = (fn) => (queue = queue.then(fn).catch((e) => console.error(e)));
  let sauceZ = 20;

  /* ---------------- build DOM ---------------- */
  const layersEl = $('#layers'), boxWrap = $('#boxWrap'), tray = $('#tray'), fly = $('#flyLayer');
  const layerEls = {};
  for (const [id, r] of Object.entries(LAYERS)) {
    const el = document.createElement('img');
    el.className = 'layer'; el.src = `assets/img/layers/${id}.webp`; el.alt = '';
    Object.assign(el.style, { left: `${(r.x / BOX.w) * 100}%`, top: `${(r.y / BOX.h) * 100}%`, width: `${(r.w / BOX.w) * 100}%`, opacity: 0, visibility: 'hidden' });
    const top = C.toppings.find((t) => t.id === id);
    el.style.zIndex = top ? top.order : 20;
    layersEl.append(el); layerEls[id] = el;
  }

  const itemButton = (cls, src, name, price) => {
    const b = document.createElement('button');
    b.className = cls; b.type = 'button'; b.setAttribute('aria-pressed', 'false');
    b.innerHTML = `<span class="${cls}__img"><img src="${src}" alt=""></span><span class="${cls}__name">${name}</span>` +
      (price !== undefined ? `<span class="${cls}__price">${price === null ? 'قیمت را بپرسید' : '+' + fa(price) + ' تومان'}</span>` : '');
    return b;
  };
  const toppingBtns = {}, sauceBtns = {}, sideBtns = {};
  for (const t of C.toppings) {
    const b = itemButton('item', img(t.tub), t.name, t.price);
    b.onclick = () => enqueue(() => toggleTopping(t.id));
    $('#toppings').append(b); toppingBtns[t.id] = b;
  }
  for (const s of C.sauces) {
    const b = itemButton('sauce', img(s.bottle), s.name);
    b.onclick = () => enqueue(() => toggleSauce(s.id));
    $('#sauces').append(b); sauceBtns[s.id] = b;
  }
  for (const s of C.sides) {
    const b = itemButton('item', img(s.img), s.name, s.price);
    b.onclick = () => enqueue(() => toggleSide(s.id));
    $('#sides').append(b); sideBtns[s.id] = b;
  }
  const presetBtns = {};
  for (const p of C.presets) {
    const b = document.createElement('button');
    b.className = 'chip'; b.type = 'button'; b.textContent = p.name;
    b.onclick = () => enqueue(() => applyPreset(p));
    $('#presets').append(b); presetBtns[p.id] = b;
  }
  $('#resetBtn').onclick = () => enqueue(() => clearAll());

  const setOn = (btn, on) => { btn.classList.toggle('is-on', on); btn.setAttribute('aria-pressed', String(on)); };

  /* ---------------- motion helpers ---------------- */
  // Fly a copy of an image along an arc between two screen rects.
  function flyImage(src, from, to, { arc = 0.35, rotate = 0, duration = 0.6, endScale = 1, endOpacity = 1 } = {}) {
    return new Promise((resolve) => {
      const el = new Image(); el.src = src; el.className = 'fly';
      el.style.width = `${from.width}px`; el.style.height = `${from.height}px`;
      fly.append(el);
      const sx = from.left, sy = from.top, ex = to.left + (to.width - from.width) / 2, ey = to.top + (to.height - from.height) / 2;
      const lift = Math.max(120, Math.abs(ex - sx) * arc);
      const p = { t: 0 };
      gsap.to(p, {
        t: 1, duration: duration * speed, ease: 'power1.inOut',
        onUpdate() {
          const t = p.t, u = 1 - t;
          const cx = (sx + ex) / 2, cy = Math.min(sy, ey) - lift; // quadratic bezier control point
          const x = u * u * sx + 2 * u * t * cx + t * t * ex, y = u * u * sy + 2 * u * t * cy + t * t * ey;
          const s = 1 + (endScale - 1) * t;
          gsap.set(el, { x, y, scale: s, rotation: rotate * Math.sin(t * Math.PI), opacity: 1 + (endOpacity - 1) * Math.pow(t, 3) });
        },
        onComplete() { el.remove(); resolve(); },
      });
    });
  }
  const rectOf = (el) => el.getBoundingClientRect();
  const bump = () => gsap.fromTo(boxWrap, { scaleY: 0.985, scaleX: 1.008 }, { scaleY: 1, scaleX: 1, duration: 0.6 * speed, ease: 'elastic.out(1, 0.35)', transformOrigin: '50% 90%' });
  const steamBurst = (ms = 2400) => { const s = $('#steam'); s.classList.add('is-strong'); clearTimeout(steamBurst.t); steamBurst.t = setTimeout(() => s.classList.remove('is-strong'), ms); };

  /* ---------------- toppings ---------------- */
  async function toggleTopping(id, fast = false) {
    const on = !state.toppings.has(id);
    const el = layerEls[id], btn = toppingBtns[id];
    if (on) {
      state.toppings.add(id); setOn(btn, true); update();
      gsap.fromTo(btn.querySelector('img'), { y: 0 }, { y: -10, yoyo: true, repeat: 1, duration: 0.15 });
      if (!fast) Sound.play('whoosh');
      const t = C.toppings.find((x) => x.id === id);
      await flyImage(img(t.tub), rectOf(btn.querySelector('img')), rectOf(el), { duration: fast ? 0.45 : 0.6, endScale: 0.55, endOpacity: 0, rotate: -12 });
      Sound.play(TOPPING_SOUND[id] || 'drop');
      gsap.set(el, { visibility: 'visible' });
      await gsap.fromTo(el, { opacity: 0, yPercent: -22, scaleY: 1.08 }, { opacity: 1, yPercent: 0, scaleY: 1, duration: 0.5 * speed, ease: 'bounce.out', transformOrigin: '50% 100%' });
      bump();
    } else {
      state.toppings.delete(id); setOn(btn, false); update();
      Sound.play('pop');
      await gsap.to(el, { opacity: 0, yPercent: -18, duration: 0.3 * speed, ease: 'power2.in' });
      gsap.set(el, { visibility: 'hidden' });
    }
  }

  /* ---------------- sauces ---------------- */
  async function toggleSauce(id, fast = false) {
    const on = !state.sauces.has(id);
    const el = layerEls[id], btn = sauceBtns[id];
    if (!on) {
      state.sauces.delete(id); setOn(btn, false); update();
      Sound.play('pop');
      await gsap.to(el, { opacity: 0, duration: 0.3 * speed });
      gsap.set(el, { visibility: 'hidden' });
      return;
    }
    state.sauces.add(id); setOn(btn, true); update();
    const bottleImg = btn.querySelector('img');
    const from = rectOf(bottleImg), target = rectOf(el);
    const w = from.width, h = from.height;
    // Bottle clone: lift, flip over the hotdog, travel along the stroke while it is revealed, then go back.
    const b = new Image(); b.src = bottleImg.src; b.className = 'fly';
    Object.assign(b.style, { width: `${w}px`, height: `${h}px` });
    fly.append(b);
    gsap.set(b, { x: from.left, y: from.top, rotation: 0 });
    bottleImg.style.visibility = 'hidden';
    const startX = target.left + target.width * 0.02 - w / 2, endX = target.left + target.width * 0.96 - w / 2;
    const nozzleY = target.top + target.height * 0.2 - h * 0.98; // upside down: nozzle at the bottom
    el.style.zIndex = ++sauceZ;
    gsap.set(el, { visibility: 'visible', opacity: 1, clipPath: 'inset(0% 100% 0% 0%)' });
    const dur = (fast ? 0.7 : 1.1) * speed;
    const tl = gsap.timeline();
    tl.to(b, { y: from.top - 30, duration: 0.18 * speed, ease: 'power2.out' })
      .to(b, { x: startX, y: nozzleY, rotation: 165, duration: 0.45 * speed, ease: 'power2.inOut' })
      .add(() => { Sound.play('squeeze'); setTimeout(() => Sound.play('squeeze'), dur * 450); })
      .to(b, { x: endX, duration: dur, ease: 'sine.inOut' }, '>')
      .to(b, { y: nozzleY + 6, duration: dur / 6, yoyo: true, repeat: 5, ease: 'sine.inOut' }, '<')
      .to(el, { clipPath: 'inset(0% 0% 0% 0%)', duration: dur, ease: 'sine.inOut' }, '<')
      .to(b, { x: from.left, y: from.top, rotation: 0, duration: 0.5 * speed, ease: 'power2.inOut' });
    await tl;
    bottleImg.style.visibility = '';
    b.remove();
    gsap.set(el, { clearProps: 'clipPath' });
  }

  /* ---------------- sides ---------------- */
  const trayEls = {};
  async function toggleSide(id, fast = false) {
    const s = C.sides.find((x) => x.id === id), btn = sideBtns[id];
    if (state.sides.has(id)) {
      state.sides.delete(id); setOn(btn, false); update();
      Sound.play('pop');
      const el = trayEls[id]; delete trayEls[id];
      await gsap.to(el, { y: -30, opacity: 0, duration: 0.3 * speed, ease: 'power2.in' });
      el.remove();
      return;
    }
    state.sides.add(id); setOn(btn, true); update();
    const el = new Image(); el.src = img(s.img); el.alt = s.name;
    if (id === 'fries') el.classList.add('is-wide');
    el.style.visibility = 'hidden';
    tray.append(el); trayEls[id] = el;
    await new Promise((r) => (el.complete ? r() : (el.onload = r)));
    if (!fast) Sound.play('whoosh');
    await flyImage(el.src, rectOf(btn.querySelector('img')), rectOf(el), { duration: 0.55, endScale: rectOf(el).height / rectOf(btn.querySelector('img')).height, rotate: 10 });
    el.style.visibility = '';
    Sound.play(s.sound);
    gsap.fromTo(el, { scaleY: 0.9, scaleX: 1.06 }, { scaleY: 1, scaleX: 1, duration: 0.5 * speed, ease: 'elastic.out(1, 0.4)' });
  }

  /* ---------------- presets ---------------- */
  async function clearAll(fast = true) {
    const jobs = [];
    for (const id of [...state.sauces]) jobs.push(toggleSauce(id, fast));
    for (const id of [...state.toppings]) jobs.push(toggleTopping(id, fast));
    await Promise.all(jobs);
  }
  async function applyPreset(p) {
    const same = (a, set) => a.length === set.size && a.every((x) => set.has(x));
    if (same(p.toppings, state.toppings) && same(p.sauces, state.sauces)) return;
    await clearAll();
    await wait(150);
    const order = [...p.toppings].sort((a, b) => C.toppings.find((t) => t.id === a).order - C.toppings.find((t) => t.id === b).order);
    for (const id of order) await toggleTopping(id, true);
    for (const id of p.sauces) await toggleSauce(id, true);
  }

  /* ---------------- pricing ---------------- */
  // The hotdog being built right now, together with the drinks/sides next to it, priced as one combo.
  function currentCombo() {
    const same = (a, set) => a.length === set.size && a.every((x) => set.has(x));
    // Sauces are free, so a menu item is matched on its toppings alone.
    const match = C.presets.find((p) => same(p.toppings, state.toppings));
    const tops = C.toppings.filter((t) => state.toppings.has(t.id));
    const sauceNames = C.sauces.filter((s) => state.sauces.has(s.id)).map((s) => s.name);
    const sides = C.sides.filter((s) => state.sides.has(s.id));
    const hotdog = match ? match.price : C.base.price + tops.reduce((a, t) => a + t.price, 0);
    const parts = tops.map((t) => t.name);
    if (sauceNames.length) parts.push(`سس: ${sauceNames.join('، ')}`);
    return {
      key: [state.toppings, state.sauces, state.sides].map((s) => [...s].sort().join(',')).join('|'),
      match,
      name: match ? `هات‌داگ ${match.name}` : 'هات‌داگ خودت',
      desc: parts.join(' · ') || 'بدون سس',
      sides: sides.map((s) => s.name),
      unit: hotdog + sides.reduce((a, s) => a + (s.price || 0), 0),
      ask: sides.some((s) => s.price === null),
    };
  }

  const cart = [];
  const cartCount = () => cart.reduce((a, l) => a + l.qty, 0);
  const cartTotal = () => cart.reduce((a, l) => a + l.unit * l.qty, 0);
  const shownTotal = { v: C.base.price };
  function update() {
    const c = currentCombo();
    $('#orderName').textContent = c.name + (c.sides.length ? ` + ${c.sides.join('، ')}` : '');
    gsap.to(shownTotal, { v: c.unit * state.qty, duration: 0.5, ease: 'power2.out', onUpdate: () => ($('#orderTotal').textContent = fa(Math.round(shownTotal.v / 1000) * 1000)) });
    $('#qtyVal').textContent = fa(state.qty);
    $('#qtyMinus').disabled = state.qty <= 1;
    $('#cartCount').textContent = fa(cartCount());
    $('#cartBtn').classList.toggle('has-items', cart.length > 0);
    for (const [id, b] of Object.entries(presetBtns)) b.classList.toggle('is-active', c.match?.id === id);
  }

  /* ---------------- cart ---------------- */
  // A static copy of the box with its visible layers, used as the cart thumbnail.
  function snapshot() {
    const s = boxWrap.cloneNode(true);
    s.querySelectorAll('#steam, #tray').forEach((n) => n.remove());
    s.querySelectorAll('[id]').forEach((n) => n.removeAttribute('id'));
    s.removeAttribute('id'); s.removeAttribute('style'); s.className = 'thumb-box';
    s.querySelectorAll('.layer').forEach((l) => { if (l.style.visibility === 'hidden') l.remove(); else Object.assign(l.style, { transform: '', clipPath: '' }); });
    return s;
  }
  // Clear the build without animating each layer (used when the finished box leaves for the cart).
  function resetBuild() {
    for (const id of state.toppings) { gsap.set(layerEls[id], { opacity: 0, visibility: 'hidden' }); setOn(toppingBtns[id], false); }
    for (const id of state.sauces) { gsap.set(layerEls[id], { opacity: 0, visibility: 'hidden' }); setOn(sauceBtns[id], false); }
    for (const id of state.sides) { trayEls[id]?.remove(); delete trayEls[id]; setOn(sideBtns[id], false); }
    state.toppings.clear(); state.sauces.clear(); state.sides.clear(); state.qty = 1;
  }

  async function addToCart() {
    const c = currentCombo(), qty = state.qty;
    const line = cart.find((l) => l.key === c.key);
    if (line) line.qty += qty; else cart.push({ ...c, qty, thumb: snapshot() });

    // the finished box flies into the cart button, then a fresh one drops onto the counter
    const from = rectOf(boxWrap), to = rectOf($('#cartBtn'));
    const clone = boxWrap.cloneNode(true);
    clone.querySelectorAll('[id]').forEach((n) => n.removeAttribute('id'));
    clone.removeAttribute('id'); clone.classList.add('fly');
    Object.assign(clone.style, { width: `${from.width}px`, height: `${from.height}px`, margin: 0 });
    fly.append(clone);
    resetBuild();
    gsap.set(boxWrap, { autoAlpha: 0 });
    Sound.play('paperQuick');
    await gsap.fromTo(clone, { x: from.left, y: from.top, scale: 1, rotation: 0 },
      { x: to.left + to.width / 2 - from.width / 2, y: to.top + to.height / 2 - from.height / 2, scale: 0.06, rotation: -10, duration: 0.7 * speed, ease: 'power2.in' });
    clone.remove();
    Sound.play('pop');
    update(); renderCart();
    gsap.fromTo('#cartCount', { scale: 1.8 }, { scale: 1, duration: 0.5, ease: 'elastic.out(1, 0.4)' });
    gsap.fromTo('#cartBtn', { rotation: -6 }, { rotation: 0, duration: 0.5, ease: 'elastic.out(1, 0.3)' });
    await gsap.fromTo(boxWrap, { autoAlpha: 1, y: -window.innerHeight * 0.6, rotation: -5 }, { y: 0, rotation: 0, duration: 0.8 * speed, ease: 'bounce.out' });
    Sound.play('drop');
    steamBurst();
  }

  function renderCart() {
    const list = $('#cartList');
    list.innerHTML = '';
    if (!cart.length) list.innerHTML = '<p class="cart__empty">سبد خالیه. یه هات‌داگ بساز و «+ به سبد» رو بزن.</p>';
    cart.forEach((l, i) => {
      const row = document.createElement('div');
      row.className = 'cline';
      row.innerHTML = `
        <div class="cline__thumb"></div>
        <div class="cline__body">
          <b class="cline__name">${l.name}</b>
          <small>${l.desc}</small>
          ${l.sides.length ? `<small>+ ${l.sides.join('، ')}</small>` : ''}
          <span class="cline__price">${fa(l.unit * l.qty)} تومان${l.ask ? ' <em>+ نوشیدنی (استعلام)</em>' : ''}</span>
        </div>
        <div class="qty qty--sm" role="group" aria-label="تعداد">
          <button type="button" data-act="plus" aria-label="یکی بیشتر">+</button>
          <span>${fa(l.qty)}</span>
          <button type="button" data-act="minus" aria-label="${l.qty > 1 ? 'یکی کمتر' : 'حذف'}">${l.qty > 1 ? '−' : '✕'}</button>
        </div>`;
      row.querySelector('.cline__thumb').append(l.thumb.cloneNode(true));
      row.querySelector('[data-act="plus"]').onclick = () => { l.qty++; Sound.play('pop'); update(); renderCart(); };
      row.querySelector('[data-act="minus"]').onclick = () => { if (--l.qty <= 0) cart.splice(i, 1); Sound.play('pop'); update(); renderCart(); };
      list.append(row);
    });
    const ask = cart.some((l) => l.ask);
    $('#cartSumLabel').textContent = `جمع کل${ask ? ' (بدون نوشیدنی)' : ''}`;
    $('#cartSum').textContent = fa(cartTotal());
    $('#checkoutBtn').disabled = !cart.length;
  }

  function openCart() {
    renderCart();
    const layer = $('#cartLayer');
    layer.hidden = false;
    const mobile = matchMedia('(max-width: 900px)').matches;
    gsap.fromTo(layer, { opacity: 0 }, { opacity: 1, duration: 0.2 });
    gsap.fromTo('.cart', mobile ? { yPercent: 100, xPercent: 0 } : { xPercent: -110, yPercent: 0 }, { xPercent: 0, yPercent: 0, duration: 0.45 * speed, ease: 'power3.out' });
    Sound.play('paperQuick');
  }
  function closeCart() {
    const mobile = matchMedia('(max-width: 900px)').matches;
    gsap.to('.cart', { ...(mobile ? { yPercent: 100 } : { xPercent: -110 }), duration: 0.3 * speed, ease: 'power2.in' });
    return gsap.to('#cartLayer', { opacity: 0, duration: 0.3, onComplete: () => ($('#cartLayer').hidden = true) });
  }

  $('#qtyPlus').onclick = () => { state.qty = Math.min(20, state.qty + 1); Sound.play('pop'); update(); };
  $('#qtyMinus').onclick = () => { state.qty = Math.max(1, state.qty - 1); Sound.play('pop'); update(); };
  $('#addBtn').onclick = () => enqueue(addToCart);
  // With an empty cart, the cart button sends the current hotdog straight in, so a single order is still one tap.
  $('#cartBtn').onclick = () => enqueue(async () => { if (!cart.length) await addToCart(); openCart(); });
  $('#cartClose').onclick = closeCart;
  $('#moreBtn').onclick = closeCart;
  $('#cartLayer').addEventListener('click', (e) => { if (e.target.id === 'cartLayer') closeCart(); });
  $('#checkoutBtn').onclick = () => { closeCart(); enqueue(showReceipt); };

  /* ---------------- receipt ---------------- */
  async function showReceipt() {
    const now = new Date();
    const no = String(Math.floor(1000 + Math.random() * 9000));
    const ask = cart.some((l) => l.ask);
    $('#receipt').innerHTML = `
      <div class="receipt__head">
        <img src="assets/img/cat-char.svg" alt="">
        <div class="receipt__brand">جلال</div>
        <div class="receipt__tag">FOOD FOR LEGENDS</div>
      </div>
      <div class="receipt__meta"><span>سفارش #${fa(+no)}</span><span>${now.toLocaleDateString('fa-IR')} · ${now.toLocaleTimeString('fa-IR', { hour: '2-digit', minute: '2-digit' })}</span></div>
      <hr>
      ${cart.map((l) => `<div class="receipt__row"><span>${l.name} × ${fa(l.qty)}<small>${l.desc}${l.sides.length ? ` · + ${l.sides.join('، ')}` : ''}</small></span><span>${fa(l.unit * l.qty)}${l.ask ? '<small>+ استعلام</small>' : ''}</span></div>`).join('')}
      <hr>
      <div class="receipt__row"><span>تعداد هات‌داگ</span><span>${fa(cartCount())}</span></div>
      <div class="receipt__row receipt__row--total"><span>جمع${ask ? ' (بدون نوشیدنی)' : ''}</span><span>${fa(cartTotal())} تومان</span></div>
      <div class="receipt__foot">${C.address}<br>تلفن: ${C.phone.replace(/\d/g, (d) => '۰۱۲۳۴۵۶۷۸۹'[d])}<br>نوش جان، افسانه! 🌭</div>`;
    const layer = $('#receiptLayer');
    layer.hidden = false;
    gsap.set('#receiptActions', { opacity: 0, y: 10 });
    gsap.fromTo(layer, { opacity: 0 }, { opacity: 1, duration: 0.25 });
    Sound.play('receipt');
    setTimeout(() => Sound.play('receipt'), 1300);
    await gsap.fromTo('#receipt', { yPercent: -100 }, { yPercent: 0, duration: 2.6 * speed, ease: 'steps(24)' });
    Sound.play('paper');
    gsap.to('#receiptActions', { opacity: 1, y: 0, duration: 0.4 });
  }
  function hideReceipt() {
    gsap.to('#receiptLayer', { opacity: 0, duration: 0.25, onComplete: () => ($('#receiptLayer').hidden = true) });
  }
  $('#againBtn').onclick = () => { hideReceipt(); cart.length = 0; renderCart(); update(); };
  $('#receiptLayer').addEventListener('click', (e) => { if (e.target.id === 'receiptLayer') hideReceipt(); });
  for (const a of [$('#callBtn'), $('#callTop')]) a.href = `tel:${C.phone}`;

  /* ---------------- mute ---------------- */
  const muteBtn = $('#muteBtn');
  const syncMute = () => { muteBtn.setAttribute('aria-pressed', String(Sound.muted)); muteBtn.setAttribute('aria-label', Sound.muted ? 'وصل صدا' : 'قطع صدا'); };
  muteBtn.onclick = () => { Sound.muted = !Sound.muted; syncMute(); try { localStorage.setItem('jalal-muted', Sound.muted ? '1' : '0'); } catch {} };
  syncMute();

  /* ---------------- preload + intro ---------------- */
  const urls = [...document.images].map((i) => i.src).concat(Object.keys(LAYERS).map((id) => `assets/img/layers/${id}.webp`));
  let loaded = 0;
  Promise.all([...new Set(urls)].map((u) => new Promise((r) => { const i = new Image(); i.onload = i.onerror = () => { loaded++; $('#loaderBar').style.width = `${(loaded / urls.length) * 100}%`; r(); }; i.src = u; })))
    .then(() => document.fonts?.ready)
    .then(() => {
      const b = $('#startBtn');
      b.disabled = false; b.querySelector('.btn__label').textContent = 'شروع ساختن';
      gsap.to('.loader', { opacity: 0, duration: 0.3 });
    });

  gsap.set(['.topbar', '.orderbar', '.panel', '.sauce', '.presets', boxWrap], { autoAlpha: 0 });
  $('#startBtn').onclick = () => {
    Sound.ac(); // unlock audio on this tap
    const tl = gsap.timeline({ defaults: { ease: 'power3.out' } });
    tl.to('#splash', { autoAlpha: 0, scale: 1.04, duration: 0.45, ease: 'power2.in' })
      .fromTo('.topbar', { autoAlpha: 1, yPercent: -100 }, { yPercent: 0, duration: 0.5 }, '-=0.1')
      .fromTo('.orderbar', { autoAlpha: 1, yPercent: 100 }, { yPercent: 0, duration: 0.5 }, '<')
      .fromTo(boxWrap, { autoAlpha: 1, y: -window.innerHeight * 0.7, rotation: -6 }, { y: 0, rotation: 0, duration: 0.9 * speed, ease: 'bounce.out' }, '-=0.2')
      .add(() => { Sound.play('drop'); setTimeout(() => Sound.play('sizzle'), 120); steamBurst(3000); }, '-=0.55')
      .fromTo('.sauce', { autoAlpha: 1, y: -60 }, { y: 0, duration: 0.6, stagger: 0.08, ease: 'back.out(2)' }, '-=0.3')
      .fromTo('.panel--toppings', { autoAlpha: 1, x: 60 }, { x: 0, duration: 0.6 }, '<')
      .fromTo('.panel--sides', { autoAlpha: 1, x: -60 }, { x: 0, duration: 0.6 }, '<')
      .fromTo('.panel .item', { autoAlpha: 0, y: 16 }, { autoAlpha: 1, y: 0, duration: 0.4, stagger: 0.04 }, '-=0.4')
      .fromTo('.presets', { autoAlpha: 1, y: 14 }, { y: 0, duration: 0.4 }, '-=0.3')
      .add(() => $('#splash').remove());
  };
})();
